50	@Service
51	public class ClinicServiceImpl implements ClinicService {
52	
53	    /** Maximum number of owners allowed per city. */
54	    private static final long CITY_CAPACITY = 50L;
55	
56	    /** At or above this many owners, a city read carries a capacity warning (approaching {@link #CITY_CAPACITY}). */
57	    private static final long CITY_CAPACITY_WARNING_THRESHOLD = 40L;
58	
59	    /** Maximum number of owners that may be created on a single day (by registration date). */
60	    private static final long DAILY_CAPACITY = 100L;
61	
62	    /** Above this many owners created today, reads carry a bulk-signup warning. */
63	    private static final long BULK_SIGNUP_THRESHOLD = 80L;
64	
65	    /** Fixed public holidays the business-day roll skips. */
66	    private static final Set<LocalDate> HOLIDAYS = Set.of(
67	        LocalDate.parse("2026-01-01"),
