275	    @Override
276	    @Transactional
277	    public void saveOwner(Owner owner, boolean declaredHouseholdMember) throws DataAccessException {
278	        if (owner.isNew()) {
279	            LocalDate effectiveDate = owner.getRegistrationDate() != null
280	                ? owner.getRegistrationDate()
281	                : LocalDate.now();
282	            owner.setRegistrationDate(toBusinessDay(effectiveDate));
283	            if (owner.getHouseholdId() == null) {
284	                owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
285	            }
286	            if (owner.getCustomerCode() == null) {
287	                owner.setCustomerCode(generateCustomerCode(owner));
288	            }
289	            if (owner.getNamesakeCount() == null) {
290	                owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
291	            }
292	            if (owner.getPossibleDuplicate() == null) {
293	                // A declared household member is not a suspected duplicate; otherwise flag it against
294	                // any existing member of the same household it collides with.
295	                Integer possibleDuplicateOf = declaredHouseholdMember ? null : findPossibleDuplicateOf(owner);
296	                owner.setPossibleDuplicateOf(possibleDuplicateOf);
297	                owner.setPossibleDuplicate(possibleDuplicateOf != null);
298	            }
299	            if (owner.getMembershipLevelCap() == null) {
300	                owner.setMembershipLevelCap(computeMembershipLevelCap(owner));
301	            }
302	        }
303	        ownerRepository.save(owner);
304	        decorateWithHouseholdMemberCount(owner);
305	    }
306	
307	    /**
308	     * Count the existing owners (before this create) that share the given first and last name,
309	     * compared case-insensitively, as required by the read-only {@code namesakeCount} field.
310	     */
311	    private int countNamesakes(String firstName, String lastName) {
312	        if (firstName == null || lastName == null) {
313	            return 0;
314	        }
315	        return (int) ownerRepository.findAll().stream()
316	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
317	                && lastName.equalsIgnoreCase(owner.getLastName()))
318	            .count();
319	    }
320	
321	    /**
322	     * Build a customer code formatted {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
323	     * canonical region derived from the owner's postcode (falling back to the city-to-region
324	     * table, then {@code 'UNKNOWN'}, as resolved by {@link LocalityResolver}) and {@code HASH8}
325	     * is the first 8 upper-case hexadecimal characters of the SHA-256 digest over the owner's
326	     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}).
327	     * <p>
328	     * If the computed code collides with an existing owner's {@code customerCode}, it is
329	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
330	     * makes it unique (e.g. {@code 'NSW-1A2B3C4D-2'}).
331	     */
332	    private String generateCustomerCode(Owner owner) {
333	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
334	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
335	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
336	        String base = region + "-" + Sha256Hex.upperHexPrefix(telephone + lastName, 8);
337	
338	        Set<String> existingCodes = ownerRepository.findAll().stream()
339	            .map(Owner::getCustomerCode)
340	            .filter(Objects::nonNull)
341	            .collect(Collectors.toSet());
342	        if (!existingCodes.contains(base)) {
343	            return base;
344	        }
345	        int n = 2;
346	        while (existingCodes.contains(base + "-" + n)) {
347	            n++;
348	        }
349	        return base + "-" + n;
350	    }
