390	    /**
391	     * Count the owners whose registration date equals today's business day, used by the
392	     * daily create-limit and bulk-signup rules.
393	     */
394	    private long countRegisteredToday() {
395	        LocalDate businessDay = toBusinessDay(LocalDate.now());
396	        return ownerRepository.findAll().stream()
397	            .filter(owner -> businessDay.equals(owner.getRegistrationDate()))
398	            .count();
399	    }
400	
401	    /**
402	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
403	     * holiday is advanced one day at a time until a non-holiday weekday is reached, while a plain
404	     * weekday is returned unchanged. Applied to the effective registration date (whether supplied
405	     * or defaulted to the server date) so that the stored {@code registrationDate}, every value
406	     * derived from it (such as the membership number's year segment) and the per-day create-limit
407	     * all use the adjusted business day.
408	     */
409	    private static LocalDate toBusinessDay(LocalDate date) {
410	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
411	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
412	            || HOLIDAYS.contains(date)) {
413	            date = date.plusDays(1);
414	        }
415	        return date;
416	    }
