418	    @Override
419	    @Transactional(readOnly = true)
420	    public boolean isIdentityKeyInUse(Owner owner) throws DataAccessException {
421	        String identityKey = owner.getIdentityKey();
422	        return ownerRepository.findAll().stream()
423	            .filter(existing -> existing != owner)
424	            .filter(existing -> !existing.isDeleted())
425	            .map(Owner::getIdentityKey)
426	            .anyMatch(identityKey::equals);
427	    }
428	
429	    /**
430	     * Resolve the id of an existing owner that the given (not yet persisted) owner is a <em>possible</em>
431	     * duplicate of, or {@code null} when there is none. A possible duplicate has a <em>different</em>
432	     * identity key from the existing owner (so it is not a hard duplicate) yet shares the Soundex code
433	     * of its last name and the same postcode, so it is worth flagging as a soft match. When several
434	     * existing owners match, the one with the lowest id is returned so the result is deterministic.
435	     * Computed once, at creation, to drive the read-only {@code possibleDuplicate}/
436	     * {@code possibleDuplicateOf} fields.
437	     */
438	    private Integer findPossibleDuplicateOf(Owner owner) {
439	        String identityKey = owner.getIdentityKey();
440	        String lastNameSoundex = Soundex.encode(owner.getLastName());
441	        String postcode = owner.getPostcode();
442	        return ownerRepository.findAll().stream()
443	            .filter(existing -> existing != owner && existing.getId() != null)
444	            .filter(existing -> !existing.isDeleted())
445	            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
446	            .filter(existing -> lastNameSoundex.equals(Soundex.encode(existing.getLastName())))
447	            .filter(existing -> Objects.equals(postcode, existing.getPostcode()))
448	            .map(Owner::getId)
449	            .min(Integer::compareTo)
450	            .orElse(null);
451	    }
452	
453	    /**
454	     * Compute the membership-level ceiling for a new owner, as required by the level-cap rule: a new
455	     * owner's {@code membershipLevel} cannot exceed one above the current maximum membership level
456	     * among its household members (existing owners sharing the same {@code householdId}, excluding
457	     * soft-deleted ones and the owner itself). Returns one above that maximum, or {@code null} when
458	     * the owner has no household id or no existing household member, in which case no cap applies.
459	     *
460	     * <p>Each existing member's level is read through {@link OwnerMapper#formatMembershipLevel},
461	     * after decorating the members with their current household member counts, so the maximum
462	     * reflects the same effective (already-capped) level the API returns for those members.
463	     */
464	    private Integer computeMembershipLevelCap(Owner newOwner) {
465	        String householdId = newOwner.getHouseholdId();
466	        if (householdId == null) {
467	            return null;
468	        }
469	        List<Owner> members = ownerRepository.findAll().stream()
470	            .filter(existing -> existing != newOwner && existing.getId() != null)
471	            .filter(existing -> !existing.isDeleted())
472	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
473	            .collect(Collectors.toList());
474	        if (members.isEmpty()) {
475	            return null;
476	        }
477	        decorateWithHouseholdMemberCount(members, members);
478	        int maxLevel = members.stream()
479	            .mapToInt(member -> ownerMapper.formatMembershipLevel(member))
480	            .max()
481	            .getAsInt();
482	        return maxLevel + 1;
483	    }
484	
485	    @Override
486	    @Transactional(readOnly = true)
487	    public String householdIdFor(String lastName, String postcode) throws DataAccessException {
488	        String key = normalizeHouseholdValue(lastName) + "|" + (postcode == null ? "" : postcode);
489	        return Sha256Hex.upperHexPrefix(key, 12);
490	    }
491	
492	    /**
493	     * Normalizes a household field (the last name) for the {@link #householdIdFor household id}
494	     * hash by trimming, collapsing runs of whitespace to a single space and lower-casing, so
495	     * differently cased or spaced but equivalent values yield the same household id.
496	     */
497	    private static String normalizeHouseholdValue(String value) {
498	        if (value == null) {
499	            return "";
500	        }
501	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
502	    }
503	
504	    /**
505	     * Populate each given owner's transient {@code householdMemberCount} with the current number of
506	     * owners that share its {@code householdId}. Owners without a household id are left at a count
507	     * of zero.
508	     *
509	     * <p>The household sizes are computed in a single pass over the owner table regardless of how
510	     * many owners are being decorated, so decorating a whole page does not re-scan per element.
511	     */
512	    private <T> T decorateWithHouseholdMemberCount(T result, Collection<Owner> owners) {
513	        if (!owners.isEmpty()) {
514	            Map<String, Long> sizeByHousehold = ownerRepository.findAll().stream()
515	                .filter(owner -> owner.getHouseholdId() != null)
516	                .collect(Collectors.groupingBy(Owner::getHouseholdId, Collectors.counting()));
517	            for (Owner owner : owners) {
518	                long size = owner.getHouseholdId() == null
519	                    ? 0L
520	                    : sizeByHousehold.getOrDefault(owner.getHouseholdId(), 0L);
521	                owner.setHouseholdMemberCount((int) size);
522	            }
523	        }
524	        return result;
525	    }
526	
527	    /**
528	     * Decorate a single (possibly {@code null}) owner with its household member count and return it.
529	     */
530	    private Owner decorateWithHouseholdMemberCount(Owner owner) {
531	        return decorateWithHouseholdMemberCount(owner, owner == null ? List.of() : List.of(owner));
532	    }
