229	        }
230	        return points;
231	    }
232	
233	    /**
234	     * Derives an owner's membership level, as required by the API's read-only
235	     * {@code membershipLevel} field: a value from 1 to 4 mapped from the owner's
236	     * {@link #formatMembershipPoints membership points} — level 1 for 0-1 points, level 2 for
237	     * 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more points.
238	     *
239	     * <p>The result is then capped by the owner's {@link Owner#getMembershipLevelCap()
240	     * membershipLevelCap}, when present: a new owner's level cannot exceed one above the highest
241	     * membership level among the household members that already existed when it was created, so the
242	     * returned level is the lower of the derived level and that stored cap. When no cap applies (no
243	     * existing household member on creation) the derived level stands.
244	     *
245	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
246	     * applied only where referenced via {@code qualifiedByName} (and when called directly, e.g.
247	     * to record the membership level on the create audit line).
248	     */
249	    @Named("formatMembershipLevel")
250	    default Integer formatMembershipLevel(Owner owner) {
251	        if (owner == null) {
252	            return null;
253	        }
254	        int points = formatMembershipPoints(owner);
255	        int level;
256	        if (points <= 1) {
257	            level = 1;
258	        }
259	        else if (points <= 3) {
260	            level = 2;
261	        }
262	        else if (points <= 5) {
263	            level = 3;
264	        }
265	        else {
266	            level = 4;
267	        }
268	        Integer cap = owner.getMembershipLevelCap();
269	        return (cap != null && cap < level) ? cap : level;
270	    }
271	
272	    /**
273	     * Derives an owner's locality, as required by the API's read-only {@code locality} field:
274	     * the {@code REGION} segment of the owner's {@code '<REGION>-<HASH8>'} customer code, so the
275	     * locality is read from the same region-and-hash identity that the customer code encodes.
276	     * When no customer code is present (e.g. an owner that predates the code), the region is
277	     * resolved directly from the postcode (falling back to the city-to-region table, else
278	     * {@code 'UNKNOWN'}), which yields the same region the code would have carried.
279	     *
280	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
281	     * applied only where referenced via {@code qualifiedByName}.
282	     */
283	    @Named("formatLocality")
284	    default String formatLocality(Owner owner) {
285	        if (owner == null) {
286	            return null;
287	        }
288	        String customerCode = owner.getCustomerCode();
289	        if (customerCode != null) {
290	            int dash = customerCode.indexOf('-');
291	            if (dash > 0) {
292	                return customerCode.substring(0, dash);
293	            }
294	        }
295	        return LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
296	    }
297	
298	    /**
299	     * Derives an owner's timezone, as required by the API's read-only {@code timezone} field:
300	     * the IANA timezone name for the owner's {@link #formatLocality locality}/region, via the
301	     * fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
302	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). Returns
303	     * {@code null} when the region has no mapped timezone (e.g. {@code 'UNKNOWN'}).
304	     *
305	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
306	     * applied only where referenced via {@code qualifiedByName}.
307	     */
308	    @Named("formatTimezone")
309	    default String formatTimezone(Owner owner) {
310	        if (owner == null) {
311	            return null;
312	        }
313	        return LocalityResolver.timezone(formatLocality(owner));
314	    }
315	
316	    /**
317	     * Derives an owner's segment, as required by the API's read-only {@code ownerSegment} field:
318	     * {@code '<TIER>_<AREA>'}, one of {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'},
319	     * {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}. {@code TIER} is {@code 'PREMIUM'}
320	     * when the owner's {@link #formatMembershipLevel membership level} is 3 or more, otherwise
321	     * {@code 'STANDARD'}. {@code AREA} is {@code 'METRO'} when the owner's {@link #formatLocality
322	     * locality} is a known region (NSW, VIC or QLD), otherwise {@code 'REGIONAL'} — a locality of
323	     * {@code 'UNKNOWN'} being exactly the case where no known region resolved.
324	     *
325	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
326	     * applied only where referenced via {@code qualifiedByName}.
327	     */
328	    @Named("formatOwnerSegment")
329	    default String formatOwnerSegment(Owner owner) {
330	        if (owner == null) {
331	            return null;
332	        }
333	        Integer level = formatMembershipLevel(owner);
334	        String tier = (level != null && level >= 3) ? "PREMIUM" : "STANDARD";
335	        String area = LocalityResolver.isKnownRegion(formatLocality(owner)) ? "METRO" : "REGIONAL";
336	        return tier + "_" + area;
337	    }
338	
339	    /**
340	     * Derives an owner's preferred contact channel, as required by the API's read-only
341	     * {@code contactPreference} field: {@code 'EMAIL'} when an email address is present,
342	     * otherwise {@code 'PHONE'}.
343	     *
344	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
345	     * applied only where referenced via {@code qualifiedByName}.
346	     */
347	    @Named("formatContactPreference")
348	    default String formatContactPreference(Owner owner) {
349	        if (owner == null) {
350	            return null;
351	        }
352	        return owner.getEmail() != null && !owner.getEmail().isEmpty() ? "EMAIL" : "PHONE";
353	    }
354	
355	    /**
356	     * Derives an owner's age band, as required by the API's read-only {@code ageBand} field:
357	     * the owner's age in whole years at the registration date, mapped to {@code 'MINOR'} (under
358	     * 18), {@code 'ADULT'} (18 to 64) or {@code 'SENIOR'} (65 or over). Returns {@code null} when
359	     * no birth date was supplied (so the field is absent), or when no registration date is yet
360	     * known against which to compute the age.
361	     *
362	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
363	     * applied only where referenced via {@code qualifiedByName}.
364	     */
365	    @Named("formatAgeBand")
366	    default String formatAgeBand(Owner owner) {
367	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
368	            return null;
369	        }
370	        int age = Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
371	        if (age < 18) {
372	            return "MINOR";
373	        }
374	        if (age < 65) {
375	            return "ADULT";
376	        }
377	        return "SENIOR";
378	    }
379	
380	    private static String initial(String name) {
381	        if (name == null || name.isEmpty()) {
382	            return "";
383	        }
384	        return Character.toUpperCase(name.charAt(0)) + ".";
385	    }
386	
387	    Owner toOwner(OwnerDto ownerDto);
388	
389	    @Mapping(target = "id", ignore = true)
390	    @Mapping(target = "pets", ignore = true)
391	    @Mapping(target = "addressLine1", ignore = true)
392	    @Mapping(target = "addressLine2", ignore = true)
393	    @Mapping(target = "address", ignore = true)
394	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
395	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
396	    @Mapping(target = "title", source = "title", qualifiedByName = "mapTitle")
397	    Owner toOwner(OwnerFieldsDto ownerDto);
398	
399	    /**
400	     * Unwraps the owner-fields' optional honorific {@code title} enum into the stored
401	     * {@code String} form (its canonical value, e.g. {@code 'DR'}), or {@code null} when no
402	     * title was supplied. This is the single place the inbound title conversion lives: it runs
403	     * on the create path via {@link #toOwner(OwnerFieldsDto)} and is called directly on the
404	     * update path, keeping both consistent.
405	     *
406	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
407	     * applied only where referenced via {@code qualifiedByName}.
408	     */
409	    @Named("mapTitle")
410	    default String mapTitle(OwnerFieldsDto.TitleEnum title) {
411	        return title == null ? null : title.getValue();
412	    }
413	
414	    /**
415	     * Sets an owner's structured and composed address fields from the supplied owner-fields,
416	     * normalizing each. This is the single place the structured-field normalization rule lives: it
417	     * runs automatically after {@link #toOwner(OwnerFieldsDto)} via {@code @AfterMapping}, and is
418	     * called directly on the update path to keep both create and update consistent.
419	     *
420	     * <p>{@code addressLine1} and {@code addressLine2} are stored in their normalized forms and
421	     * {@code address} is set to the {@link #composeAddress composed} effective address.
422	     */
423	    @AfterMapping
424	    default void applyAddressFields(OwnerFieldsDto ownerDto, @MappingTarget Owner owner) {
425	        if (ownerDto == null) {
426	            return;
427	        }
428	        owner.setAddressLine1(normalizeAddress(ownerDto.getAddressLine1()));
429	        owner.setAddressLine2(normalizeAddress(ownerDto.getAddressLine2()));
430	        owner.setAddress(composeAddress(ownerDto));
431	    }
432	
433	    /**
434	     * Composes the effective, normalized postal address for an owner from the supplied fields,
435	     * preferring the structured form over the flat one. When a non-blank {@code addressLine1} is
436	     * present, the result is the normalized {@code addressLine1} with the normalized
437	     * {@code addressLine2} appended after a single space when an {@code addressLine2} is present;
438	     * otherwise it is the normalized flat {@code address}. Each part is normalized through
439	     * {@link #normalizeAddress} (trim, collapse whitespace, upper-case, expand {@code ST -> STREET},
440	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}).
441	     */
442	    default String composeAddress(OwnerFieldsDto ownerDto) {
443	        if (ownerDto == null) {
444	            return null;
445	        }
446	        String line1 = normalizeAddress(ownerDto.getAddressLine1());
447	        if (line1 != null && !line1.isEmpty()) {
448	            String line2 = normalizeAddress(ownerDto.getAddressLine2());
449	            return (line2 != null && !line2.isEmpty()) ? line1 + " " + line2 : line1;
450	        }
451	        return normalizeAddress(ownerDto.getAddress());
452	    }
453	
454	    /**
455	     * Normalizes a postal address into a canonical form: surrounding whitespace is trimmed and
456	     * internal runs of whitespace collapsed to a single space, the value is upper-cased and common
457	     * abbreviations are expanded as whole tokens ({@code ST -> STREET}, {@code RD -> ROAD},
458	     * {@code AVE -> AVENUE}). So {@code '  12  main  st '} is stored and returned as
459	     * {@code '12 MAIN STREET'}.
460	     *
461	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
462	     * only where referenced via {@code qualifiedByName}.
463	     */
464	    @Named("normalizeAddress")
465	    default String normalizeAddress(String address) {
466	        return AddressNormalizer.normalize(address);
467	    }
468	
469	    /**
470	     * Normalizes a telephone number into canonical E.164 form: a leading {@code '+'} and country
471	     * code are kept when present, otherwise country code {@code '+61'} is assumed and a single
472	     * leading {@code '0'} is dropped from the national digits; spaces, dashes and brackets are
473	     * stripped and the result must contain 8 to 15 digits after the {@code '+'}. So
474	     * {@code '0412 345 678'} is stored and returned as {@code '+61412345678'}.
475	     *
476	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
477	     * only where referenced via {@code qualifiedByName} (and when called directly, e.g. on update).
478	     *
479	     * @throws org.springframework.samples.petclinic.util.InvalidTelephoneException if the number
480	     *         cannot form a valid E.164 value (handled as a 400 Bad Request).
481	     */
482	    @Named("normalizeTelephone")
483	    default String normalizeTelephone(String telephone) {
484	        return TelephoneNormalizer.toE164(telephone);
485	    }
486	
487	    /**
488	     * Normalizes an email address by lower-casing it, so it is stored and returned in a
489	     * canonical form. The schema-level {@code format: email} on {@code OwnerFieldsDto.email}
490	     * guarantees any value present is a syntactically valid address.
491	     *
492	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
493	     * applied only where referenced via {@code qualifiedByName} (and when called directly,
494	     * e.g. on update).
495	     */
496	    @Named("normalizeEmail")
497	    default String normalizeEmail(String email) {
498	        return email == null ? null : email.toLowerCase(Locale.ROOT);
499	    }
500	
501	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
502	
503	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
504	
505	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
506	        OwnerPageDto ownerPageDto = new OwnerPageDto();
507	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
508	        ownerPageDto.setPage(ownerPage.getNumber());
509	        ownerPageDto.setSize(ownerPage.getSize());
510	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
511	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
512	        return ownerPageDto;
513	    }
514	}
