36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.samples.petclinic.service.IdempotencyKeyRegistry;
43	import org.springframework.samples.petclinic.util.AddressValidator;
44	import org.springframework.samples.petclinic.util.DisposableEmailValidator;
45	import org.springframework.samples.petclinic.util.PostcodeValidator;
46	import org.springframework.samples.petclinic.util.RegistrationDateValidator;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    private final IdempotencyKeyRegistry idempotencyKeyRegistry;
75	
76	    private final OwnerAuditEventPublisher auditEventPublisher;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper,
82	                                 IdempotencyKeyRegistry idempotencyKeyRegistry,
83	                                 OwnerAuditEventPublisher auditEventPublisher) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	        this.idempotencyKeyRegistry = idempotencyKeyRegistry;
89	        this.auditEventPublisher = auditEventPublisher;
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
95	        Collection<Owner> owners;
96	        if (lastName != null) {
97	            owners = this.clinicService.findOwnerByLastName(lastName);
98	        } else {
99	            owners = this.clinicService.findAllOwners();
100	        }
101	        if (owners.isEmpty()) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
110	        Owner owner = this.clinicService.findOwnerById(ownerId);
111	        if (owner == null) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(toOwnerDtoWithWarning(owner), HttpStatus.OK);
115	    }
116	
117	    /** Map an owner to its DTO, setting the read-only {@code bulkSignupWarning} and
118	     *  {@code capacityWarning} flags the same way for every owner response. */
119	    private OwnerDto toOwnerDtoWithWarning(Owner owner) {
120	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
121	        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupDay());
122	        ownerDto.setCapacityWarning(this.clinicService.isCityApproachingCapacity(owner.getCity()));
123	        return ownerDto;
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
129	        // A create retried with an already-seen idempotency key returns the originally created
130	        // owner with 200, rather than creating a duplicate.
131	        Integer existingId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey).orElse(null);
132	        if (existingId != null) {
133	            Owner existing = this.clinicService.findOwnerById(existingId);
134	            if (existing != null) {
135	                return new ResponseEntity<>(toOwnerDtoWithWarning(existing), HttpStatus.OK);
136	            }
137	        }
138	        HttpHeaders headers = new HttpHeaders();
139	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
140	        AddressValidator.validate(owner.getAddress());
141	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
142	        DisposableEmailValidator.validate(owner.getEmail());
143	        RegistrationDateValidator.validate(owner.getRegistrationDate());
144	        if (this.clinicService.isDailyRegistrationAtCapacity()) {
145	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
146	        }
147	        // The household id is deterministic from (lastName, postcode), so owners sharing a last name
148	        // and postcode are automatically the same household. It no longer gates duplicate detection
149	        // (that is the identity key alone) but still drives household-derived fields.
150	        owner.setHouseholdId(this.clinicService.householdIdFor(owner.getLastName(), owner.getPostcode()));
151	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
152	        // Duplicate detection is the single identity key: reject only when the new owner's whole
153	        // identity key (SHA-256 over normalizedTelephone|lowerEmail|soundex(lastName)) matches an
154	        // existing, non-deleted owner's. Two owners with the same last name and postcode but different
155	        // telephones have distinct keys and are created as a soft match rather than rejected.
156	        if (this.clinicService.isIdentityKeyInUse(owner)) {
157	            return new ResponseEntity<>(HttpStatus.CONFLICT);
158	        }
159	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
160	            return new ResponseEntity<>(HttpStatus.CONFLICT);
161	        }
162	        this.clinicService.saveOwner(owner, sharesHousehold);
163	        this.idempotencyKeyRegistry.remember(idempotencyKey, owner.getId());
164	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
165	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
166	            ownerMapper.formatMembershipLevel(owner), ownerMapper.formatMembershipNumber(owner));
167	        this.auditEventPublisher.ownerCreated(owner, ownerMapper.formatMembershipLevel(owner));
168	        OwnerDto ownerDto = toOwnerDtoWithWarning(owner);
169	        headers.setLocation(UriComponentsBuilder.newInstance()
170	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
171	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
177	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
178	        if (currentOwner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        PostcodeValidator.validate(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
182	        DisposableEmailValidator.validate(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
183	        ownerMapper.applyAddressFields(ownerFieldsDto, currentOwner);
184	        AddressValidator.validate(currentOwner.getAddress());
185	        currentOwner.setCity(ownerFieldsDto.getCity());
186	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
187	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
188	        currentOwner.setLastName(ownerFieldsDto.getLastName());
